globalThis.ANDE_CHUNKS["122bf5759cf4bd40572376cb10c67605cee5005f88dab38381aca8623142c0f5"] = [{"id":"kuaishou_social:11025","sourceKey":"kuaishou_social","company":"快手","title":"策略产品经理（联盟流量）-【商业化联盟】","city":"北京","category":"产品类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/11025","duty":"1、负责联盟流量价值识别、评估与验证体系建设，提升流量预算匹配效率进而撬动收益；\n2、从流量和预算多视角深入业务，通过严谨的数据分析、内外部调研等洞察策略优化空间，能独立挖掘业务机会，明确迭代方向；\n3、建立数据分析和评估机制，制定中长期产品规划，把控产品节奏并协调算法/引擎/数分合作团队推动高质量落地交付。","requirements":"1、大学本科及以上学历，具备3-5年工作经验，至少一年商业化策略产品经验，熟悉广告全链路及策略优化方法，优先具备AI/大模型经验；\n2、数据分析与研究学习能力强，熟练掌握SQL、数据分析、效果评估等工具和方法；\n3、思维活跃、逻辑严谨，具备良好的创新意识与跨团队协作能力。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:11756","sourceKey":"kuaishou_social","company":"快手","title":"GR协作专员【成都】","city":"成都","category":"运营类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/11756","duty":"1、负责处理平台内监管侧舆情隐患问题，及时识别并响应潜在舆情风险，独立处理外部投诉，完成企业在监管驻场的业务支持工作，并高效落实公司及监管部门交办的各项任务；\n2、熟悉市场监管部门的工作流程及相关法律法规，对舆情事件具有高度敏感性和判断力，具备较强的逻辑思维与沟通协调能力，能够及时发现、整理并上报潜在风险问题；具备良好的沟通与谈判能力，能够坚定维护平台立场，合理争取权益；\n3、负责对外部投诉事件进行数据统计与汇总，定期输出投诉处理报告，分析投诉趋势及热点问题，为提升服务质量提供数据支持，并具备一定的运营经验，能够为团队持续赋能；\n4、协助相关部门对用户问题进行整理、数据沉淀与定期复盘，针对监管类投诉问题，高效协调内部资源，与相关职能部门紧密协作，推动问题妥善解决，防范风险升级；\n5、熟悉市场监管部门的工作流程及相关法律法规条款，对法规内容有深入理解和实际运用能力，能够及时掌握并跟进法规的更","requirements":"1、大专及以上学历，具备1年以上大型企业客服流程运营相关经验；\n2、对舆情及风险事件具有高度敏感性，熟悉相关政策法规，具备良好的逻辑思维能力，能够及时捕捉变化并灵活调整运营策略；\n3、具备数据分析能力，能从日常工作中提取并分析数据，识别潜在问题、趋势与机会；熟练运用数据分析工具，开展深度分析并撰写详实报告；\n4、具备优秀的内外部沟通与协作能力，能够与合作伙伴、监管机构等外部资源保持高效、良好的沟通，推动信任建立与目标协同达成；\n5、具备应对突发事件的快速响应能力和持续学习能力，面对复杂问题时能迅速定位并提出有效解决方案；积极关注行业新动态、新工具，不断提升自身专业竞争力。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:12317","sourceKey":"kuaishou_social","company":"快手","title":"游戏计算机图形学算法工程师- 【游戏事业部】","city":"杭州/上海","category":"工程类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/12317","duty":"1、图形渲染技术解决方案的预研与开发；\n2、引擎图形功能的使用、维护与扩展优化；\n3、美术表现的技术支持，工具链的开发与优化；\n4、持续跟进学术界和游戏界最新技术的进展，并总结分享给团队成员；\n5、渲染管线设计和优化。","requirements":"1、本科及以上学历，3-7年工作经验；\n2、掌握C++，熟悉一门脚本语言；\n3、具备良好的数学及计算机图形学基础，有良好的英文阅读能力；\n4、掌握图形渲染基础算法和核心渲染技术，熟悉可编程管线原理，Shader编写，熟悉各种效率分析和优化技术；\n5、了解并使用过一款主流3D图形引擎（Unity、UE4），有引擎相关工具制作经验、次世代渲染和优化经验优先；\n6、具备较强的自我推动能力，热爱游戏开发；\n7、熟悉主流大模型，熟练运用Copilot、Codex等AI工具提升工作效能，能将AI有效集成到日常开发流程。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:12318","sourceKey":"kuaishou_social","company":"快手","title":"主管","city":"成都","category":"内容评级类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/12318","duty":"1、协助制定平台的安全策略和机制，带领业务线团队对内容进行审查，发现并处理违规及敏感信息；\n2、确定审核规范，制定运营编辑流程，明确工作细节要求，确定审核频次、时间、尺度；负责内容编辑和巡查，制定内容运营编辑策略及落地执行；\n3、全面统业务线团队招聘、培训、考核等事宜；\n4、团队日常管理监督，优化业务流程，完善工作标准规范，善用系统自动化方案提升运营编辑效率保障产品安全。","requirements":"1、大专及以上学历；\n2、有良好的政治觉悟与素养优先，有较强的政治敏感度和鉴别能力优先，共青团员和党员优先；\n3、互联网安全信息领域3-5年以上工作经历，团队人数超100+管理经验，具备敏锐的风险洞察能力；\n4、熟悉互联网内容管控政策条例，具备视频或图文运营编辑业务管理经验；\n5、准确识别内容核心风险、产品逻辑风险和运营编辑业务痛点，能够结合业务形态制定解决方案；\n6、具备较强的具备较强的数据分析、风险识别与控制能力；\n7、具备良好的沟通表达能力，逻辑思维清晰，具有较强的责任感、创新能力、团队协作精神和沟通合作意识；\n","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:12401","sourceKey":"kuaishou_social","company":"快手","title":"数值策划- 【游戏事业部】","city":"杭州/上海/广州","category":"产品类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/12401","duty":"1、参与设计游戏经济系统、养成系统、技能、关卡等数值模块，与各模块负责策划，及程序、美术协作完成项目开发；\n2、根据各系统的设计目标，完成如商品定价、投放回收、成长曲线、战斗及技能公式、关卡难度等数值细节的配置与测试调优。","requirements":"1、3年及以上数值策划工作经验（有完整上线项目经验者优先）；\n2、数学能力强，建模能力强，思维敏锐；\n3、具备强大的逻辑分析能力和设计调整能力；\n4、热爱游戏，至少有2款卡牌RPG、ARPG、MMORPG、SLG、或竞技类游戏的深度体验经历；\n5、具有优秀的沟通能力和团队协作能力；\n6、熟悉主流AI智能体的使用，有vibe coding经验更优。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:12410","sourceKey":"kuaishou_social","company":"快手","title":"高级3D角色制作设计师- 【游戏事业部】","city":"杭州","category":"设计类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/12410","duty":"1、擅长复杂布料、写实PBR风格模型制作及引擎表现相关工作；\n2、有大型MMO、换装类游戏研发经验优先；\n3、熟练掌握插片毛发制作工艺、有较好的造型剪影审美归纳能力；\n2、具备良优秀的3D模型制作能力以及材质表现能力；\n3、具备良好的语言表达能力及合作态度；\n4、需要保持与策划，设计，技术等相关部门保持紧密的合作与沟通。","requirements":"1、有3-5年及以上的3D角色制作工作经历；\n2、设计/绘画相关专业优先；\n3、熟练掌握3DMax/Maya、Zbrush/Mudbox、Substance Designer/Painter、Quixel suit、Marvelous Designer、Photoshop等相关制作软件；\n4、能熟练使用手绘板进行作画，有扎实的绘画技巧和良好的色彩感；\n5、具备良好的沟通能力；\n6、具备良好的自学能力及学习意愿；\n7、热爱游戏开发，做事积极主动。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:12472","sourceKey":"kuaishou_social","company":"快手","title":"商业分析专家（品牌方向）-【商业化】","city":"北京","category":"分析类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/12472","duty":"1、理解广告业务逻辑，通过数据梳理和数据分析对增长、供需问题/机会点进行归因，识别并解决业务的本质问题；\n2、结合客户诉求、产研能力、用户流量效率等维度，进行专题分析和数据建模，输出有商业价值对洞察并推动落地；\n3、具备流量实验、分析的能力，制定产品北极星指标并助力产品决策；\n4、制定资源价格、政策，跟踪保障政策落地，预算盘点与监控，提升资源使用效率。\n","requirements":"1、本科及以上学历，熟练掌握数据分析/商业分析的必备分析技能，掌握多项能力加分；\n2、了解广告业务、广告主诉求、商业化人群价值、流量效率优化思路；\n3、对数据能力要求高，精通SQL，熟悉数据分析常用算法，R/python熟练者有限；\n4、有好奇心，具备独立思考能力，能够抓住业务本质，提出自己的见解和意见。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:12604","sourceKey":"kuaishou_social","company":"快手","title":"3D动作设计师-【游戏事业部】（上海）","city":"上海","category":"设计类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/12604","duty":"1、负责游戏中角色、NPC等动作设计和制作；\n2、配合动作摆镜头的表现；\n3、剧情镜头的表现。\n","requirements":"1、美术专业毕业，传统动画专业最佳，3年以上3D游戏动作工作经验；\n2、熟悉游戏商用引擎，熟练使用3DMAX、等软件；\n3、对人类，四足动物，怪物等运动规律有深入了解，能赋予角色性格和生物生命力；\n4、能够独立完成各种类角色动作的设计和制作（包括骨骼绑定、蒙皮等），并能梳理完整的制作流程和规范；\n5、能熟练运用镜头语言，对主机游戏或者影视镜头有一定研究，对镜头结合动作表现有一定经验；\n6、了解不同风格动画表现方式；\n7、配合主美完成任务，需要有良好的执行力，良好的沟通能力，有很好的工作自律性，能承受较强的工作压力，具有团队合作精神；\n8、有参与完整大型项目经验者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:12810","sourceKey":"kuaishou_social","company":"快手","title":"数据分析师（AI&大模型方向）-【数据分析中心】","city":"北京","category":"分析类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/12810","duty":"1、构建全面的、准确的、能反映服务业务线特征的宏观、微观指标体系，并基于业务监控指标体系，及时发现与定位业务问题；\n2、与算法技术（社区科学线）进行紧密合作，用系统科学的分析方法，为算法进行优化方向探索，并提出有效的迭代建议；\n3、通过专题分析，对业务问题进行深入分析，对公司内外部数据进行挖掘，在深入的产品理解与用户洞察基础上，自主发掘课题，提出有实效的建议；\n4、沉淀分析思路与框架，具有一定的数据产品能力，能够自行进行数据可视化，并能提炼数据产品需求，与相关团队（如技术开发团队） 协作并推动数据产品的落地；\n5、与相关团队协作进行数据建模工作，推动业务部门的数据化运营，能够基于数据分析、量化建模、市场调研等工具对产品和市场进行理解和刻画，解决各种复杂商业分析问题，能独立完成从方案设计、数据加工与分析，到结论展示的整个流程；\n6、与相关团队协作（如数据运营团队）组织数据技术与产品相关的理念","requirements":"1、统计、数学、信息技术、生物统计、管理科学与数据分析本科以上学历，2-5年左右相关工作经历；\n2、具有一定概率统计基础，良好的数据敏感度，了解常用的机器学习算法，能从海量数据中提炼核心结果，有丰富的数据分析、挖掘、清洗和建模的经验者优先；\n3、熟练独立编写商业数据分析报告，及时发现和分析其中隐含的变化和问题；\n4、有大项目经验，有丰富的跨团队、部门的项目资源整合能力，能够独立开展研究项目 ；\n5、熟练使用SQL、Python或者R，对数据进行处理、分析和可视化呈现，能高效的与数据技术团队进行沟通；\n6、很强的逻辑思维、产品理解和商业洞察力，能以合适分析框架解决各种复杂问题，批判性思考；\n7、对流行文化、PGC/UGC视频、直播、综艺、音乐、电影等有兴趣及一定认知者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:12903","sourceKey":"kuaishou_social","company":"快手","title":"心理辅导员","city":"铜仁","category":"运营类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/12903","duty":"1、负责员工心理健康评估，提供心理方向的指导；\n2、根据业务需要，策划和组织活动，促进业务发展并提升员工心理活力；\n3、风险员工预警，转介及后续跟进管理；\n4、组织开展职场现状调查，根据结果，防范风险，协调各部门制定解决方案。","requirements":"1、本科及以上学历，心理学、教育学、社会学等相关专业；\n2、熟练使用EXCEL、SPSS等统计分析软件；\n3、2年以上工作经历，有测评、咨询、培训、团辅、访谈经验者优先；\n4、对公司文化高度认同，有较强的学习能力、责任心和执行力。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:13007","sourceKey":"kuaishou_social","company":"快手","title":"数据分析师","city":"成都","category":"分析类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/13007","duty":"1、根据既有绩效方案，准确核算用户体验部员工绩效数据；\n2、解答绩效疑问，通过培训、文档、考核等形式协助绩效方案顺利落地；\n3、协同HR、业务部门更新完善用户体验部员工绩效方案，对绩效方案的可行性、合理性进线验证，并给出相应建议；\n4、通过绩效核算结果主动发现业务问题，并推动落地改善。","requirements":"1、专科及以上学历，应用数学、统计学、计算机、经济学相关专业优先；\n2、2年以上互联网行业数据统计分析、数据挖掘相关工作经验；\n3、具备较强数据的处理能力，熟练掌握SQL、EXCEL等相关数据提取处理工具；\n4、熟悉Python、SAS或SPSS等分析工具优先；\n5、具有较强的思维逻辑能力，良好的数据敏感度；\n6、具有客服行业相关经验者优先；\n7、具有人员绩效计算相关经验者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:13215","sourceKey":"kuaishou_social","company":"快手","title":"资深明星运营-【主站】","city":"北京","category":"运营类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/13215","duty":"1、深耕娱乐行业，具备成熟明星及经纪公司资源，能独立完成明星引入、合作谈判及运营方案制定；\n2、负责明星账号的长期运营，结合明星特质、内容方向与平台资源，制定增长策略，打造优质内容与账号影响力；\n3、统筹并推动明星项目落地执行，包括但不限于明星内容 IP、商业合作、演出合作等，保障项目效果达成；\n4、能结合 AI 工具提升运营效率，应用于内容策划、热点洞察、方案生成、数据分析及项目复盘，推动运营决策优化。","requirements":"1、本科及以上学历，5 年以上互联网明星业务或娱乐运营相关经验，具备独立策划及项目管理能力；\n2、熟悉娱乐行业生态，拥有成熟优质的明星、经纪公司及上下游资源；\n3、熟悉娱乐行业合作模式，具备与各类明星团队、经纪公司合作及谈判经验；\n4、具备良好的沟通、策划与推进能力，亲和力强，有耐心与责任心；\n5、对 AI 有较强接受和应用能力，能熟练使用 AI 工具辅助内容运营、策略分析和日常提效者优先；\n","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:13458","sourceKey":"kuaishou_social","company":"快手","title":"质培组长","city":"烟台","category":"审核类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/13458","duty":"岗位内容：\n1、根据业务发展需要，制定一线团队人才梯队发展方案，建立和完善培训体系及培训制度；\n2、基于培训业务规划，制定各模块能力需求和岗位能力素质模型；制定各团队培训计划及方案；\n3、负责搭建质控体系，通过对质控数据的全面分析，发现一线业务差异点及业务流程问题并推进改善；\n4、主导搭建线上培训学习考核系统、智能质检系统。\n","requirements":"任职要求：\n1、本科以上学历，具备3年以上审核团队管理经验；\n2、抗压能力强，善于沟通和资源协调、有跨团队、多部门协作项目经验；\n3、对业务和数据敏感，能快速发现问题和解决问题，结合业务经验，找到业务改善机会；\n4、有搭建线上培训系统或智能质检系统经验优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:13572","sourceKey":"kuaishou_social","company":"快手","title":"多模态内容理解算法工程师/专家","city":"北京","category":"算法类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/13572","duty":"1、负责快手短视频多模态内容理解工作，应用计算机视觉、NLP、多模态融合等技术，提升短视频内容体系建设、推荐、搜索的效果和体验；\n2、基于多模态模型在下游业务上的应用，包括并不限于多模态分类、标签、caption等文本生成等；\n3、负责计算机多模态理解方向前沿问题的研究，参与建设并持续保持部门在多模态业界的技术先进性，保持创新的同时将业界SOTA模型持续优化并落地至线上获得收益。 \n\n","requirements":"1、硕士及以上学历，有大规模模型训练、压缩、蒸馏、微调等经验，熟悉megatron、deepspeed等框架者优先；\n2、精通至少一种技术语言，包括但不限于Java、C/C++、C#、Python等；\n3、熟悉至少一种深度学习框架（如 TensorFlow、PyTorch），对深度学习基础理论和大规模实践有较深理解；\n4、有较强的学术调研、文献阅读和算法实现能力，优秀的独立开发、调试能力，有高质量论文、开源项目、ACM竞赛经历、相关学术会议组织的权威比赛获奖经历或落地项目产出者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:14239","sourceKey":"kuaishou_social","company":"快手","title":"生产力分析","city":"成都","category":"客服类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/14239","duty":"1、负责用户体验部业务进线的预测，配合运营团队完成业务量分发和人力规划交付；\n2、与运营团队/业务团队建立流程改进和流程标准化，推动相关体系完善；\n3、追踪预测结果并对数据进行追踪分析；\n4、沉淀预测思路以及数据分析思路和框架，负责整体预测体系的提升。","requirements":"1、数学、统计学、计算机相关专业优先，对数据分析有强烈兴趣者优先；\n2、有呼叫中心业务进线预测经验或3年以上呼叫中心工作流程管理经验优先；\n3、有过预测&排班系统使用经验优先；\n4、精通 EXCEl、SQL，熟练使用 R/Python 进行数据清洗、分析，掌握 Tableau 等 BI 工具尤佳。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:14294","sourceKey":"kuaishou_social","company":"快手","title":"用户产品经理（海外业务）-【KSIB】","city":"北京","category":"产品类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/14294","duty":"1、负责快手国际化产品的基础框架体验和基础功能设计，围绕顶导、底导、个人页、通知页、各类播控功能等开展工作；\n2、理解海外业务的发展方向，通过前瞻性的框架设计提升对新业务的扶持能力，同时对接各业务部门，制定平台基础规范和接入准则；\n3、理解国际化短视频用户特征，结合不同国家的情况，提出有建设性的产品方案并推动落地，提升用户消费体验。","requirements":"1、本科及以上学历，3年以上短视频产品工作经验，有国际化产品相关工作经验可优先；\n2、具备较强的需求挖掘、数据分析（SQL）及应用和创新能力；\n3、具备较强的沟通协调能力，拥有强烈的责任心和团队合作精神，出色的学习能力。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:14361","sourceKey":"kuaishou_social","company":"快手","title":"数据科学家(损益方向)-【主站】","city":"北京","category":"分析类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/14361","duty":"1、分析和挖掘海量数据，衡量与预测各类业务战略与策略的长期价值与收益，从ROI的角度评估各类业务的效率、提出效率优化的方向等；\n2、从增效度量视角出发，基于AB实验设计、因果推断、运筹规划等手段，解决直播和运营业务域内效果评估、策略迭代场景下的复杂度量问题；\n3、建立合理的损益指标与度量体系，引导业务持续发展；制定统一的度量规范，以公平、科学、透明的度量管理规范推动业务增长；\n4、将业务问题抽象为统一的数学框架，横向输出至各业务线DS/DA团队，赋能各业务线的科学度量与分析工作。\n","requirements":"1、3年及以上数据科学/数据分析/计量经济相关工作经验；\n2、硕士及以上，统计学、经济学、运筹、计算机等相关专业；\n3、扎实的因果推断与实验设计能力：熟悉 AB 实验全流程、CUPED/DiD/合成控制/工具变量等准实验方法，能独立判断方法适用性并落地；\n4、较强的业务问题抽象能力：能把模糊的业务问题拆解为可度量的数学框架与可验证的指标体系；\n5、熟练使用SQL，Python或R中进行数据分析、可视化呈现等；\n6、目标导向，影响力驱动，拥有创新意识、协同落地能力、跨团队沟通表达能力。对短视频产品及相关业务场景有浓厚兴趣。\n\n加分项\n1、有内容生态、流量分发等业务领域的度量经验；\n2、有跨团队驱动方法论落地的经历。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:14507","sourceKey":"kuaishou_social","company":"快手","title":"行业运营专家（生鲜方向）-【电商】","city":"杭州/北京","category":"运营类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/14507","duty":"1、负责行业招商策略制定，熟悉生鲜食品行业核心产业带，通过定向招募、多方协同、工具提效等策略实现优质商家引入；\n2、了解生鲜食品行业商家特性和经营模式，能结合平台资源和商家禀赋给到商家高效可靠的经营指引，并输出有效商家成长SOP；\n3、通过数据分析不同场域、不同经营模式商家的冷启差异，反哺招商方向调整，实现招商路径最优；\n4、具备良好的中台视角，能够有效推进招商策略的落地执行，并拿到招商结果；\n5、具备良好的内外部资源整合能力，能通过外部生态合作，内部协同多种方式，助力招商目标达成。","requirements":"1、3-5年工作经验，有过生鲜食品行业招商经验优先；\n2、具备生鲜食品行业相关生态及商家资源，电商平台工作经历优先；\n3、具备一定数据分析能力，有较强业务洞察、发现问题和解决问题能力；\n4、乐观抗压，自驱力强，强目标感，拿结果能力强。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:14553","sourceKey":"kuaishou_social","company":"快手","title":"高级Java开发工程师（分析平台）-【数据平台】","city":"北京/上海","category":"工程类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/14553","duty":"1、深度参与公司级智能数据分析平台的研发，负责智能问答（ChatBI）、Text2SQL、智能看板解读、智能配置看板等核心智能化能力的设计与实现；\n2、基于 LangChain4j/LangGraph4j等框架构建企业级 AI 应用架构，利用 RAG、Agent、 Prompt Engineering、模型微调等技术，解决数据分析场景下的语义理解与复杂推理问题；\n3、负责微服务架构的设计与优化，整合大数据 OLAP 引擎（如 Doris/ClickHouse）与 AI 服务，构建高性能、低延迟的数据中台服务；\n4、跟进 LLM 在数据分析领域的最新进展（如 NL2SQL 优化、多轮对话上下文管理），将创新技术转化为可落地的产品能力，提升数据分析的准确率与效率。","requirements":"1、本科及以上学历，计算机相关专业，3年以上后端研发经验，精通 Java 编程，具有扎实的多线程及分布式系统架构设计能力；\n2、具备 LLM 应用开发实战经验，熟悉 Prompt Engineering，深入理解 RAG 流程及向量数据库应用，熟悉 LangChain、LangGraph4j、Spring AI 等开发框架；\n3、有 Text2SQL / NL2SQL 调优经验者极佳，了解数据分析业务，有BI产品研发经验者优先；\n4、具备优秀的代码规范和系统设计能力，能解决 AI 应用落地中的高并发、长链路治理等挑战；\n5、具备良好的技术热情与沟通能力，能够主动思考业务痛点，推动 AI 技术在数据场景下落地。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:14871","sourceKey":"kuaishou_social","company":"快手","title":"海外质检专员","city":"成都","category":"运营类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/14871","duty":"岗位职责：\n 1、负责人工审核质量的结果质检，输出质量情况反馈报表，促进结果质量持续提升； \n2、按要求执行质检方案，前置发现风险漏洞，促进过程质量的有效保障；\n3、参与质量相关项目，审计并评估全链路关键节点方案有效性，通过pdca进行相关问题驱动闭环。 \n4、对质检数据的结果准确率负责，确保质检数据的结果正确性。\n\n","requirements":"任职要求:\n1、大专及以上学历，具备葡萄牙语听说读写能力；\n2、有良好的政治觉悟与素养优先，有较强的政治敏感度与鉴别能力优先，共青团员和党员优先；\n3、认真负责，责任心强，个性乐观，善于沟通，有较好的团队意识及积极向上的价值观。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:14911","sourceKey":"kuaishou_social","company":"快手","title":"社群质培专员","city":"淮安","category":"客服类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/14911","duty":"1、负责社群渠道的群聊消息与工作执行的质检，对员工服务质量和SOP执行情况负责；\n2、负责定期对员工进行业务培训，帮助员工提升用户服务能力和工具与流程的掌握度；\n3、负责社群渠道问题解决流程搭建与维护，保证员工问题解决的实效性；\n4、负责日常数据统计与分析，通过数据挖掘问题点并推动解决。\n","requirements":"1、具备1年以上在线客服经验优先，有质检或培训经验优先；\n2、具备良好的阅读理解力，能从用户表达中准确理解用户的意思；\n3、具备良好的用户感知力，能明白用户想要什么；\n4、具备良好的表达能力，能用简单易懂的方式表达观点；\n5、做事认真仔细不马虎。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:14986","sourceKey":"kuaishou_social","company":"快手","title":"商业分析师（达人方向）-【电商】","city":"北京","category":"分析类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/14986","duty":"1、看清达人业务经营表现，识别经营机会和做工策略，完成达人长短期经营预测，并与业务结合输出落地策略，协助业务拿到结果；\n2、完善达人的核心指标体系，追踪并分析关键经营指标的变化趋势，挖掘经营机会，监控业务风险，协助业务决策判断；\n3、重点专题研究，根据业务发展过程中的问题与痛点，基于内外部调研与数据分析提出业务优化策略建议，并推动解决方案落地（分析方向包括但不限于流量增长，用户表现，商品效率等）；\n4、持续关注市场和行业情况，根据需要协助业务负责人制定/调整业务方案。","requirements":"1、3年以上战略咨询或互联网商业分析经验，需要有良好的专业技能，包括但不限于行业研究、数据分析、项目推进等，并熟悉Hive、SQL、Excel、Python等数据结构和相关工具的使用；\n2、有结构化思考与分析能力，有良好的商业敏感度，既能有全局判断，也能对具体问题深入下钻；\n3、有较强的沟通能力，能够跨部门多团队协作，同时有解决问题的责任心和抗压能力； \n4、学习能力强，勤于思考，抗压能力强，追求快速成长。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:14994","sourceKey":"kuaishou_social","company":"快手","title":"Java开发工程师/专家（广告交易中台）-【商业化】","city":"北京","category":"工程类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/14994","duty":"1、负责快手商业化的资金体系建设以及相关方向的解决方案研发工作；\n2、理解资金业务内容，承担业务相关的技术攻坚，主导核心服务的编码和上线；\n3、积极主动，通过对财务资金业务的深入理解发现系统的瓶颈，能够主动发现系统问题并进行推进解决；\n4、对现有业务系统的架构进行抽象和升级，提升系统的效率和平台化能力，提升整体的研发效率。\n","requirements":"1、三年以上Java开发经验，有扎实的计算机基础知识和编程功底；\n2、精通多线程编程，熟悉JVM，熟悉常见的开源分布式中间件、缓存、消息队列等，熟悉MySQL，熟悉Linux下的DevOps；\n3、熟悉面向对象设计，有一定的系统架构设计能力；\n4、有大型复杂业务系统或财务系统研发经验优先；\n5、热爱技术，对代码质量和开发规范有近乎苛刻的要求，善于沟通与团队协作；具有一定的技术前瞻性，对技术有热情，善于研究分析业内主流产品技术实现，为团队引入创新的技术、创新的解决方案，用创新的思路解决问题。\n","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:15006","sourceKey":"kuaishou_social","company":"快手","title":"推荐算法工程师-【生活服务】","city":"北京","category":"算法类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/15006","duty":"生活服务业务是快手商业化增速最快的业务之一，包含线索和本地团购类型行业。一起来探索端到端生成式推荐OneLoc，Scaling Law，近场分发场景下的多模态表征，基于RL的长期价值最大化。\n\n1、负责生服广告和自然内容推荐系统的核心精排模型算法持续迭代优化，提升业务的核心指标，帮助快手生服业务高速增长；\n2、基于快手的海量用户和商家数据，探索使用机器学习、迁移学习、强化学习、LLM、diffusion、多模态技术、博弈论等前沿技术来解决快手生活服务业务所面临的多元异构数据的挑战，将前沿技术在生服业务上落地，推动业务高速发展；\n3、通过数据分析挖掘业务潜在机会，面向流量投放侧和广告主优化侧进行算法设计和效果优化。","requirements":"1、计算机科学、数学、统计学等相关专业硕士及以上学历，精通C/C++、Java、Python等至少一门编程语言；\n2、有机器学习、数据挖掘、自然语言处理、推荐系统等相关研究经验或工作经验优先，在相关领域顶级会议上发表论文者优先；\n3、强烈的技术热情和学习渴望，对技术驱动业务有不懈的追求；\n4、具备优秀的分析和解决问题的能力，良好的沟通能力，较强的团队合作精神。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:15057","sourceKey":"kuaishou_social","company":"快手","title":"合规运营专家-【生活服务】","city":"北京","category":"运营类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/15057","duty":"1、负责快手生活服务商家及商品准入的风险治理工作，熟悉相关政策法规，对商品发布规范进行管理，确保商品的完整性、一致性，确定性、合规性；\r\n2、通过行业风险解读，联动风控、产研、算法、审核一线等团队，建立商品准入风险防控体系部署；\r\n3、商家及商品生命周期内的风险深入挖掘分析，利用平台产品算法能力，制定合理有效的风险治理策略，综合评估风险管控收益与人力成本，实现商品风险事前防控的效率最优；\r\n4、保持专业敏感性和风险预测能力，持续不断对策略进行迭代调优；\r\n5、推动风险管控链路中的审核、策略、数据监控等产品工具的完善；\r\n6、项目管理：协同业务、产品，算法，技术等多部门团队，系统化闭环落地治理方案；\r\n7、数据运营：深刻理解业务的基础上，利用数据思维，对业务进行深入分析，挖掘风险特征，保证策略迭代。","requirements":"1、本科及以上学历，工作三年以上，有电商平台、本地生活业务等商家及商品准入、治理、合规管理、风险策略管理经验、商品及商品策略体系建设的经验；\n2、有数据驱动能力，有较强的数据分析能力，通过数据发现问题，并可以用策略以及产品化能力给出解决方案；\n3、具备项目管理能力，一定抗压能力，可以跨多团队协调沟通，管理过程，快速拿到结果。\n","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:15061","sourceKey":"kuaishou_social","company":"快手","title":"平台治理专家-【生活服务】","city":"北京","category":"运营类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/15061","duty":"1、基于平台业务发展及市场变化，制定生活服务业务治理管理规则，并持续优化；\r\n2、通过用户洞察及数据分析，发现并归纳治理过程中影响商家理解及体验的关键问题，制定相关策略并推动相关部门进行优化迭代；\r\n3、作为治理产运中台，与产品、数据、技术团队协作，完善治理产品链路及功能，保障用户体验的同时帮助治理构建高效的治理生态；\r\n4、搭建及优化规则对外的规则中心产品，提升产品可用性及传播性。","requirements":"1、3年及以上规则治理的相关岗位经验，有治理产品运营、规则教育或规则运营工作经验优先；\n2、本科及以上学历，优秀的数据分析及总结能力，能通过数据发现及验证工作价值；\n3、结构化思维能力，良好的策划、跨团队横向沟通协调及落地能力；\n4、熟悉本地或电商行业优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:15063","sourceKey":"kuaishou_social","company":"快手","title":"体验运营专家-【生活服务】","city":"北京","category":"运营类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/15063","duty":"1、分析洞察快手本地生活用户体验痛点，设计并推进消费者购物保障体系、权益机制，提升用户满意度；\n2、通过产品运营、活动运营、营销策略等手段，增加权益触达及透传，提升权益的覆盖度及用户感知度；\n3、设计细分人群、细分品类服务及权益体系，降低用户流失；\n4、拆解项目指标，具备分析能力，能够独立完成项目效果评估。\n","requirements":"1、本科以上学历，3年以上互联网/O2O/电商平台工作经验，有售后服务设计、体验改善或管理、产品运营、用户运营至少一个方向相关经验；\n2、具备良好的用户思维，同理心强，善于整合内部资源，良好沟通及合作意识，推动项目落地；\n3、独立完成过体验改善项目设计及落地、有过本地生活业务经验者优先；\n4、熟练掌握Sql，具备独立完成数据挖掘及分析的能力。\n","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:15075","sourceKey":"kuaishou_social","company":"快手","title":"垂类/策略运营Leader-【主站】","city":"北京","category":"运营类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/15075","duty":"1、带领团队以垂类内容生态体系建设为核心，通过创作者引入、优质内容输出，驱动特定用户增长及活跃，借助AI工具建立内容健康度监测机制，提升决策效率；\n2、以行业视角切入，负责垂类创作者引入、成长、管理体系的建立，形成差异化的生态竞争壁垒；\n3、以数据及整体业务发展趋势为依据，输出策略，制定方案，拿到结果，沉淀方法论，建立行业口碑；\n4、对数据进行深度洞察，将业务经验转化为可复用的AI辅助分析流程，提升团队整体策略制定效率；\n5、具备多团队跨部门协同能力，推动合作并落地。","requirements":"1、本科及以上学历，5年以上互联网运营经验，有团队管理经验；\n2、熟悉短视频领域及内容生态，了解创作者运营与商业逻辑；\n3、具备较强的逻辑性与数据能力，能敏锐洞察用户需求，并将数据结论转化为可落地的运营策略；\n4、具备良好的沟通协作与执行能力，责任心强；\n5、能带领、激励团队，具备选人、育人的能力；\n6、对AI工具在运营场景的应用有实践经验或强烈探索意愿，能推动AI辅助工作流在团队内落地，提升整体运营效率。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:15097","sourceKey":"kuaishou_social","company":"快手","title":"区域策略运营（北京）-【本地生活】","city":"北京","category":"运营类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/15097","duty":"1、负责本地生活业务的策略运营，围绕目标拆解、资源规划＆政策制定、经营分析、策略专项等一系列动作，协同业务团队共同达成目标；\n2、通过对业务开展深度洞察与分析，发现行业机会点与风险点，面向业务团队输出核心策略和重点项目规划，推进落地并带来业务实际提升；\n3、协同行业相关各横向团队及内部团队，作为行业信息接口，实现跨部门协作方案落地。\n","requirements":"1、本科及以上学历，2年以上工作经验，有本地生活、电商等相关行业从业经验优先，有策略运营、商业分析经验者优先；\n2、有结构化思考与分析能力，兼具大局观与对细节的敏感，善于表达与沟通；\n3、天生乐观，遇事积极主动、责任心强、变通能力强、自我驱动力强、能适应高强度工作节奏；\n4、熟练使用SQL/Tableau/Power BI等分析或可视化工具者加分。\n","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou_social:15171","sourceKey":"kuaishou_social","company":"快手","title":"问答运营","city":"成都","category":"运营类","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.kuaishou.cn/recruit/e/#/official/social/job-info/15171","duty":"职位描述:\n1、负责对接BP团队，根据公司业务需要设计并长期维护可以清晰定位用户问题的标准问和末级标准问体系；\n2、负责对接流程、客服和BP团队，完善解答方案，对A的准确性和有效性负责，推动优化服务流程；\n3、负责对接知识文档、培训、客服和质检团队，确保标准问相关知识的传递高效准确，协同提升客服选择准确率；\n4、负责对接AI运营团队，协助完成机器人的QA建设工作，协助提高AI问题解决率。\n\n","requirements":"任职要求:\n1、大学专科学历及以上；\n2、一年以上用户体验/客服相关工作经验优先，熟悉QA结构及业务细节者优先；\n3、具有很强的阅读理解、文字表达及总结能力；\n4、沟通协作能力强，有较强的领悟力及学习能力，具备团队意识；\n5、逻辑清晰，能够深入挖掘和分析，定位问题根因并思考解决方案；\n6、积极主动，有较强的上进心及自驱力；\n7、情绪稳定，能承受较大的工作压力。","description":"","jdComplete":false,"sourceStatus":null}];
